/**
 * Inkvec branding: the LogoLabs flask above the INKVEC wordmark, drawn in a reserved
 * strip at the bottom of every Inkvec node. Copper on the node's own ground, so it
 * reads on light and dark ComfyUI themes alike. Purely visual -- remove this file (and
 * WEB_DIRECTORY in __init__.py) and the nodes work exactly as before.
 */
import { app } from "../../scripts/app.js";

const BRAND = {
  flask: "data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%22720%20550%20700%20970%22%20fill%3D%22%23c9754a%22%3E%0A%3Cpath%20d%3D%22M%20881.984%20591.726%20C%20909.088%20592.132%20936.829%20591.866%20963.981%20591.887%20L%20964.051%20615.134%20C%20987.819%20614.909%201017.69%20614.432%201041.08%20615.648%20C%201040.93%20607.346%201040.69%20600.253%201041.98%20592.045%20C%201069.11%20592.348%201096.88%20591.998%201124.06%20591.953%20L%201123.92%20675.668%20L%201101.07%20675.765%20C%201095.31%20774.162%201119.89%20868.607%201055.36%20953.552%20C%201004.92%201019.95%20937.496%201064.82%20878.928%201123.13%20C%20845.28%201156.38%20816.712%201194.4%20794.144%201235.97%20C%20767.017%201286.42%20741.545%201353.22%20780.436%201404.37%20C%20796.668%201425.52%20824.772%201443.38%20851.877%201445.43%20C%20877.696%201447.4%20906.17%201446.57%20932.261%201446.6%20L%201080.96%201446.69%20L%201197.09%201446.81%20C%201210.8%201446.82%201244.73%201447.6%201257.07%201445.9%20C%201273.88%201443.68%201289.75%201436.88%201302.95%201426.25%20C%201322.04%201410.93%201332.82%201389.99%201335.14%201365.73%20C%201337.48%201341.57%201330.09%201317.48%201314.6%201298.79%20C%201282.06%201259.91%201239.06%201266.08%201193.98%201266.11%20L%201064.24%201266.18%20C%201007.04%201266.21%20963.782%201274.83%20923.019%201226.4%20C%20902.441%201198.45%20902.862%201175%20902.924%201142.3%20C%20912.343%201133.33%20929.852%201117.98%20939.887%201110.13%20C%20940.427%201142.3%20933.166%201185.04%20957.055%201209.47%20C%20975.922%201228.76%20996.316%201230.57%201021.97%201229.58%20C%201035.66%201229.06%201050.27%201230.01%201064.04%201229.64%20C%201123.95%201229.84%201183.88%201229.63%201243.79%201229.78%20C%201278.77%201229.84%201312.9%201244%201337.05%201269.48%20C%201360.56%201294.24%201373.23%201327.36%201372.25%201361.49%20C%201371.21%201395.65%201356.25%201427.91%201330.85%201450.78%20C%201293.97%201484.58%201264.51%201482.67%201218.46%201482.55%20L%201136.27%201482.52%20L%20960.971%201482.87%20C%20928.505%201482.94%20895.26%201483.33%20863.01%201482.84%20C%20824.574%201482.3%20784.504%201464.07%20758.904%201435.1%20C%20675.08%201340.22%20761.832%201202.37%20828.1%201124.18%20C%20850.986%201097.18%20877.862%201073.68%20903.55%201050.22%20C%20901.884%201021.1%20903.068%20980.916%20903.063%20950.824%20L%20903.075%20765.518%20L%20903.206%20711.487%20C%20903.313%20700.62%20904.014%20686.497%20903.106%20676.093%20C%20895.901%20675.719%20889.159%20675.649%20881.94%20675.611%20C%20882.424%20648.129%20881.982%20619.316%20881.984%20591.726%20z%20M%20964.007%20675.527%20C%20955.974%20675.648%20947.939%20675.718%20939.905%20675.736%20L%20939.967%201018.59%20C%20957.908%201003.76%20976.395%20987.535%20992.628%20970.848%20C%201042.17%20921.753%201064.98%20876.954%201065.28%20806.604%20L%201064.84%20676.083%20L%201040.87%20676.051%20C%201041.64%20666.978%201041.33%20661.135%201040.9%20651.947%20C%201019.24%20651.252%20986.821%20650.561%20965.356%20651.5%20C%20963.031%20654.329%20963.936%20670.679%20964.007%20675.527%20z%20M%201062.08%20612.678%20C%201061.97%20626.562%201062.1%20641.194%201061.69%20655%20L%201095.78%20654.97%20C%201098.9%20654.996%201101.7%20655.476%201104.18%20653.836%20C%201105.4%20645.43%201104.6%20621.8%201104.64%20611.911%20C%201099.78%20612.021%201078.39%20611.957%201074.37%20612.466%20L%201062.08%20612.678%20z%22%3E%3C%2Fpath%3E%0A%3C%2Fsvg%3E",
  wordmark: "INKVEC",
  color: "#c9754a",
  strip: 56, // reserved at the bottom of the node, flask + gap + tracked caps
};

const flask = new Image();
let flaskReady = false;
flask.onload = () => {
  flaskReady = true;
};
flask.src = BRAND.flask;

app.registerExtension({
  name: "inkvec.brand",
  beforeRegisterNodeDef(nodeType, nodeData) {
    if (!nodeData.name || !String(nodeData.name).startsWith("Inkvec")) return;

    // Reserve the strip in the size the frontend computes from the widgets, so the
    // brand never sits on top of one.
    const originalComputeSize = nodeType.prototype.computeSize;
    nodeType.prototype.computeSize = function (out) {
      const size = originalComputeSize
        ? originalComputeSize.apply(this, arguments)
        : out || [0, 0];
      return [size[0], size[1] + BRAND.strip];
    };

    nodeType.prototype.onDrawForeground = function (ctx) {
      if (!ctx || (this.flags && this.flags.collapsed)) return;
      const w = this.size && this.size[0];
      const h = this.size && this.size[1];
      if (!w || !h) return;
      const cx = w / 2;
      const flaskH = 34;
      const flaskW = flaskH * (700 / 970); // the flask's own viewBox aspect
      const top = h - BRAND.strip + 4;
      ctx.save();
      if (flaskReady) {
        ctx.drawImage(flask, cx - flaskW / 2, top, flaskW, flaskH);
      }
      ctx.fillStyle = BRAND.color;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      try {
        ctx.letterSpacing = "3px";
      } catch (e) {
        /* older canvases: the wordmark just reads tighter */
      }
      ctx.font = "600 10px ui-monospace, Consolas, Menlo, monospace";
      ctx.fillText(BRAND.wordmark, cx + 1.5, h - 7);
      try {
        ctx.letterSpacing = "0px";
      } catch (e) {
        /* as above */
      }
      ctx.restore();
    };
  },
});
